using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace ApiServer
{
    public class CircuitBreaker
    {
        private int _failureCount;
        private int _successCount;
        private readonly int _threshold;
        private readonly TimeSpan _recoveryTimeout;
        private DateTime _lastFailureTime;
        private CircuitState _state;
        private readonly object _lock = new object();

        public enum CircuitState { Closed, Open, HalfOpen }

        public CircuitBreaker(int threshold = 5, int recoverySeconds = 30)
        {
            _threshold = threshold;
            _recoveryTimeout = TimeSpan.FromSeconds(recoverySeconds);
            _state = CircuitState.Closed;
        }

        public CircuitState State => _state;

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open)
                {
                    if (DateTime.UtcNow - _lastFailureTime >= _recoveryTimeout)
                    {
                        _state = CircuitState.HalfOpen;
                        return true;
                    }
                    return false;
                }
                return true; // HalfOpen allows one request
            }
        }

        public void RecordSuccess()
        {
            lock (_lock)
            {
                _successCount++;
                if (_state == CircuitState.HalfOpen)
                {
                    _state = CircuitState.Closed;
                    _failureCount = 0;
                }
            }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailureTime = DateTime.UtcNow;
                if (_failureCount >= _threshold)
                    _state = CircuitState.Open;
            }
        }
    }

    public class RequestDeduplicator
    {
        private readonly Dictionary<string, DateTime> _seen;
        private readonly TimeSpan _window;

        public RequestDeduplicator(TimeSpan window)
        {
            _seen = new Dictionary<string, DateTime>();
            _window = window;
        }

        public bool IsDuplicate(string requestKey)
        {
            CleanExpired();
            if (_seen.ContainsKey(requestKey))
                return true;
            _seen[requestKey] = DateTime.UtcNow;
            return false;
        }

        private void CleanExpired()
        {
            var expired = _seen.Where(kv => DateTime.UtcNow - kv.Value > _window)
                               .Select(kv => kv.Key).ToList();
            foreach (var key in expired)
                _seen.Remove(key);
        }
    }

    public class RateLimiter
    {
        private readonly Dictionary<string, List<DateTime>> _clientRequests;
        private readonly int _maxRequests;
        private readonly TimeSpan _window;

        public RateLimiter(int maxRequests, TimeSpan window)
        {
            _clientRequests = new Dictionary<string, List<DateTime>>();
            _maxRequests = maxRequests;
            _window = window;
        }

        public bool IsAllowed(string clientId)
        {
            if (!_clientRequests.ContainsKey(clientId))
                _clientRequests[clientId] = new List<DateTime>();

            var requests = _clientRequests[clientId];
            var cutoff = DateTime.UtcNow - _window;
            requests.RemoveAll(t => t < cutoff);

            if (requests.Count >= _maxRequests)
                return false;

            requests.Add(DateTime.UtcNow);
            return true;
        }
    }

    public class SearchIndex
    {
        private readonly Dictionary<string, HashSet<string>> _index;

        public SearchIndex()
        {
            _index = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            SeedData();
        }

        private void SeedData()
        {
            var items = new[] { "widget", "gadget", "sprocket", "flange", "bearing" };
            foreach (var item in items)
            {
                for (int i = 1; i <= item.Length; i++)
                {
                    var prefix = item.Substring(0, i);
                    if (!_index.ContainsKey(prefix))
                        _index[prefix] = new HashSet<string>();
                    _index[prefix].Add(item);
                }
            }
        }

        public List<string> Search(string query)
        {
            var results = new List<string>();
            var normalized = NormalizeQuery(query);
            foreach (var term in normalized)
            {
                if (_index.TryGetValue(term, out var matches))
                    results.AddRange(matches);
            }
            return results.Distinct().ToList();
        }

        private List<string> NormalizeQuery(string query)
        {
            // Split on whitespace and generate all substring prefixes for fuzzy matching
            var terms = query.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            var normalized = new List<string>();
            foreach (var term in terms)
            {
                // Generate all substrings for partial matching
                for (int start = 0; start < term.Length; start++)
                {
                    for (int len = 1; len <= term.Length - start; len++)
                    {
                        normalized.Add(term.Substring(start, len));
                    }
                }
            }
            return normalized;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class SearchController : ControllerBase
    {
        private static readonly CircuitBreaker _circuitBreaker = new CircuitBreaker(5, 30);
        private static readonly RateLimiter _rateLimiter = new RateLimiter(100, TimeSpan.FromMinutes(1));
        private static readonly RequestDeduplicator _deduplicator = new RequestDeduplicator(TimeSpan.FromSeconds(5));
        private static readonly SearchIndex _searchIndex = new SearchIndex();

        [HttpGet("query")]
        public IActionResult Query([FromQuery] string q, [FromQuery] string clientId = "anonymous")
        {
            if (string.IsNullOrWhiteSpace(q))
                return BadRequest("Query parameter 'q' is required");

            if (q.Length > 256)
                return BadRequest("Query too long");

            if (!_rateLimiter.IsAllowed(clientId))
                return StatusCode(429, "Rate limit exceeded");

            if (!_circuitBreaker.AllowRequest())
                return StatusCode(503, "Service temporarily unavailable");

            var requestKey = $"{clientId}:{q}";
            if (_deduplicator.IsDuplicate(requestKey))
                return Ok(new { cached = true, results = new string[0] });

            try
            {
                var results = _searchIndex.Search(q);
                _circuitBreaker.RecordSuccess();
                return Ok(new { cached = false, results });
            }
            catch (Exception)
            {
                _circuitBreaker.RecordFailure();
                return StatusCode(500, "Internal error");
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.MapControllers();
            app.Run();
        }
    }
}
